class Cart:
    def __init__(
        self,
        free_shipping_threshold: float = 100.0,
        shipping_cost: float = 15.0,
    ) -> None:
        self.free_shipping_threshold = free_shipping_threshold
        self.shipping_cost = shipping_cost
        self._items = []
        self._discounts = []
        self._vouchers = []

    def add(self, name: str, unit_price: float, quantity: int = 1) -> None:
        self._items.append((name, unit_price, quantity))

    def apply_discount(self, percent: float) -> None:
        self._discounts.append(percent)

    def apply_voucher(self, amount: float) -> None:
        self._vouchers.append(amount)

    def total(self) -> float:
        subtotal = sum(price * quantity for _, price, quantity in self._items)
        savings = max(
            [0.0]
            + [subtotal * percent / 100 for percent in self._discounts]
            + [min(amount, subtotal) for amount in self._vouchers]
        )
        shipping = (
            0.0 if subtotal >= self.free_shipping_threshold else self.shipping_cost
        )
        return round(subtotal - savings + shipping, 2)
